<?php
require '../config.php';
$d=body();$token=$d['token']??'';$qid=(int)($d['question']??0);$selected=array_values(array_unique(array_filter(array_map('intval',$d['answers']??[]))));if(!$selected)json_response(['error'=>'Välj ett svar.'],422);
$s=db()->prepare("SELECT p.id player_id,p.game_id,q.time_limit,q.points,g.question_started_at FROM jolt_players p JOIN jolt_games g ON g.id=p.game_id JOIN jolt_questions q ON q.quiz_id=g.quiz_id AND q.id=? WHERE p.token=? AND g.status='question'");$s->bind_param('is',$qid,$token);$s->execute();$x=$s->get_result()->fetch_assoc();if(!$x)json_response(['error'=>'Frågan är stängd.'],409);$elapsed=max(0,(int)((microtime(true)-strtotime($x['question_started_at']))*1000));$limit=(int)$x['time_limit']*1000;if($elapsed>$limit)json_response(['error'=>'Tiden är ute.'],409);
$valid=[];$correct=[];$result=db()->query('SELECT id,is_correct FROM jolt_answers WHERE question_id='.$qid);while($row=$result->fetch_assoc()){$valid[]=(int)$row['id'];if($row['is_correct'])$correct[]=(int)$row['id'];}foreach($selected as $id)if(!in_array($id,$valid,true))json_response(['error'=>'Ogiltigt svar.'],422);$ok=count(array_intersect($selected,$correct))>0?1:0;$gameId=(int)$x['game_id'];$participants=max(1,(int)db()->query('SELECT COUNT(*) c FROM jolt_players WHERE game_id='.$gameId)->fetch_assoc()['c']);
try{db()->begin_transaction();$s=db()->prepare('SELECT points_awarded FROM jolt_responses WHERE player_id=? AND question_id=? FOR UPDATE');$s->bind_param('ii',$x['player_id'],$qid);$s->execute();$old=$s->get_result()->fetch_assoc();$answered=(int)db()->query('SELECT COUNT(*) c FROM jolt_responses WHERE game_id='.$gameId.' AND question_id='.$qid)->fetch_assoc()['c'];$speed=max(0,1-($elapsed/$limit));$answerOrder=max(0,1-($answered/$participants));$points=$ok?(int)round((int)$x['points']*(.5+.35*$speed+.15*$answerOrder)):0;$ids=implode(',',$selected);if($old){$s=db()->prepare('UPDATE jolt_responses SET answer_ids=?,is_correct=?,response_ms=?,points_awarded=? WHERE player_id=? AND question_id=?');$s->bind_param('siiiii',$ids,$ok,$elapsed,$points,$x['player_id'],$qid);$s->execute();}else{$s=db()->prepare('INSERT INTO jolt_responses(game_id,player_id,question_id,answer_ids,is_correct,response_ms,points_awarded) VALUES(?,?,?,?,?,?,?)');$s->bind_param('iiisiii',$gameId,$x['player_id'],$qid,$ids,$ok,$elapsed,$points);$s->execute();}$delta=$points-(int)($old['points_awarded']??0);$s=db()->prepare('UPDATE jolt_players SET score=GREATEST(0,score+?) WHERE id=?');$s->bind_param('ii',$delta,$x['player_id']);$s->execute();db()->commit();json_response(['ok'=>true]);}catch(Throwable $e){db()->rollback();json_response(['error'=>'Svaret kunde inte sparas.'],500);}
